/**
 * S8 · PanIndiaMap — §13 (rebuilt in Round 2, ask 13)
 * bg: --surface-alt
 *
 * An accurate dot-matrix world map (Natural Earth 1:10m, India point-of-view edition,
 * generated by scripts/gen-world-dots.mjs into worldDots.ts). India is drawn with the
 * Government of India depiction — Jammu & Kashmir and Ladakh complete, nothing cut at
 * the top — in burgundy; the rest of the world is a muted silver-grey dot backdrop.
 * Chandigarh is the pulsing origin. Arcs are UNLABELLED: dense inside India (the Pan
 * Bharat delivery network, today), and a few longer, lighter arcs fanning across the
 * world to carry the *ambition* ("Crafted in Bharat, made for the world.").
 *
 * HONESTY (§19): no export or country claims, no country / city names, no flags. The
 * world arcs are illustrative direction, and the caption says so. See ADR-012.
 *
 * Motion (once, on scroll-in): outline draws, India dots settle, domestic arcs draw, a
 * light dot travels each arc once, then the world arcs fan out. transform / opacity /
 * stroke-dashoffset only. Reduced motion: the finished map, no pulse.
 */

'use client';

import { useEffect, useRef, useState } from 'react';
import Link from 'next/link';
import { useGSAP } from '@gsap/react';
import { gsap, ScrollTrigger, DURATIONS, EASINGS } from '@/lib/motion';
import { useMaskRise } from '@/hooks/useMotion';
import { site } from '@/content/site';
import { pictogramPaths, type PictogramName } from '@/components/brand/Pictogram';
import PartPicto from '@/components/products/PartPicto';
import { productGroups, productsByGroup } from '@/content/products';
import {
  WORLD_DOTS, INDIA_DOTS, INDIA_OUTLINE, INDIA_ISLANDS,
  STEP_WORLD_U, STEP_INDIA_U, INDIA_SCALE, INDIA_CLON, INDIA_CLAT, project,
} from './worldDots';

gsap.registerPlugin(ScrollTrigger);

/* Two-layer composition: a wide dotted world band behind (Africa, Europe, Asia, Australia, the
   Americas as a faint far edge), India enlarged in front by INDIA_SCALE about its centre. Points
   inside India go through `ind()`, world points through plain `project()`. */
const ind = (lon: number, lat: number) => {
  const c = project(INDIA_CLON, INDIA_CLAT);
  const p = project(lon, lat);
  return { x: c.x + (p.x - c.x) * INDIA_SCALE, y: c.y + (p.y - c.y) * INDIA_SCALE };
};
const ORIGIN = ind(76.78, 30.73); // Chandigarh (verified base)
const IND_T = `translate(${project(INDIA_CLON, INDIA_CLAT).x} ${project(INDIA_CLON, INDIA_CLAT).y}) scale(${INDIA_SCALE}) translate(${-project(INDIA_CLON, INDIA_CLAT).x} ${-project(INDIA_CLON, INDIA_CLAT).y})`;

/* Regional points inside India — generic, unlabelled (no cities claimed). */
const DOMESTIC: [number, number][] = [
  [73.5, 23.5], [75.5, 15.5], [77.6, 11.8], [80.2, 13.4], [79.0, 21.0], [82.5, 17.5],
  [85.8, 20.5], [88.3, 22.6], [91.7, 26.2], [94.2, 25.6], [84.5, 25.6], [78.2, 26.8],
  [74.2, 27.2], [70.8, 22.6], [76.4, 9.6], [81.2, 23.6],
];
/* Broad world points — illustrative direction only (the ambition), no names. They sit out
   in the other continents so every one of these arcs visibly leaves India's border. */
const WORLD: [number, number][] = [
  [8, 48], [-8, 8], [26, -22], [46, 28], [122, 14], [122, 38], [140, 36], [134, -26], [-40, -12], [18, 18],
];

/* Ten domestic endpoints carry a part symbol from the catalogue (the parts we dispatch); the rest
   stay plain studs. Illustrative only: no part is claimed for any particular region. */
const BADGE: Partial<Record<number, PictogramName>> = {
  13: 'float-valve', 0: 'push-cock', 1: 'waste-pipe', 2: 'ventilation-jalli', 14: 'gasket',
  3: 'door-lock', 4: 'hinge', 6: 'adjustable-leg-insert', 7: 'connecting-bush', 8: 'f-bush',
};
const BADGE_R = 10.5;
const ICON = 13; /* pictogram size inside a badge, in map units */

/* The catalogue as a unit chart: one row per product family, one symbol tile per published part. */
const MANIFEST = productGroups
  .map(g => ({ g, parts: productsByGroup(g.id) }))
  .filter(r => r.parts.length > 0);
const MANIFEST_TOTAL = MANIFEST.reduce((n, r) => n + r.parts.length, 0);

const VB = { x: 0, y: 30, w: 1075, h: 505 };
const inFrame = (p: { x: number; y: number }) =>
  p.x > VB.x + 8 && p.x < VB.x + VB.w - 8 && p.y > VB.y + 8 && p.y < VB.y + VB.h - 8;

const round = (n: number) => Math.round(n * 10) / 10;

function arcPath(to: { x: number; y: number }, lift: number) {
  const mx = (ORIGIN.x + to.x) / 2;
  const my = (ORIGIN.y + to.y) / 2;
  const dist = Math.hypot(to.x - ORIGIN.x, to.y - ORIGIN.y);
  const cy = my - Math.min(dist * lift, 130);
  return `M${round(ORIGIN.x)} ${round(ORIGIN.y)}Q${round(mx)} ${round(cy)} ${round(to.x)} ${round(to.y)}`;
}

const domestic = DOMESTIC.map(([lo, la]) => {
  const p = ind(lo, la);
  return { p, d: arcPath(p, 0.28) };
});
const world = WORLD.map(([lo, la]) => {
  const p = project(lo, la);
  return { p, d: arcPath(p, 0.26) };
});

const CSS = `
.pim { position: relative; background: var(--surface-alt); padding: calc(var(--section-y) + 16px) var(--grid-page-padding) calc(var(--section-y) + 24px); overflow: hidden; }
.pim-inner { max-width: calc(var(--grid-max) + 2 * var(--grid-page-padding)); margin: 0 auto; }
.pim-head { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--space-md); align-items: end; }
.pim-label { display: flex; align-items: center; gap: 10px; font-size: 0.75rem; text-transform: uppercase; letter-spacing: 0.16em; color: var(--muted); font-weight: 600; font-family: var(--font-archivo); margin-bottom: var(--space-sm); }
.pim-label i { width: 24px; height: 2px; background: var(--burgundy); display: inline-block; }
.pim-h2 { font-family: var(--font-archivo); font-variation-settings: "wdth" 125; font-size: clamp(1.75rem, 3.5vw, 2.75rem); font-weight: 650; line-height: 1.1; letter-spacing: -0.025em; color: var(--ink); max-width: 20ch; text-wrap: balance; margin-bottom: var(--space-md); }
.pim-lead { font-size: 1.0625rem; line-height: 1.65; color: var(--body); max-width: 52ch; }
.pim-legend { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: var(--space-sm); }
.pim-legend li { display: flex; align-items: center; gap: var(--space-sm); font-size: 0.9375rem; color: var(--ink); font-weight: 500; line-height: 1.35; }
.pim-legend svg { flex: none; }
.pim-frame { position: relative; margin-top: var(--space-xl); overflow: hidden; border-top: 1px solid var(--grey-warm); border-bottom: 1px solid var(--grey-warm); background: linear-gradient(180deg, rgba(255,255,255,.7), transparent 55%); }
.pim-stage { overflow: hidden; -webkit-mask-image: linear-gradient(to right, transparent, var(--ink) 9%, var(--ink) 91%, transparent), linear-gradient(to bottom, transparent, var(--ink) 7%, var(--ink) 93%, transparent); -webkit-mask-composite: source-in; mask-image: linear-gradient(to right, transparent, var(--ink) 9%, var(--ink) 91%, transparent), linear-gradient(to bottom, transparent, var(--ink) 7%, var(--ink) 93%, transparent); mask-composite: intersect; }
.pim-svg { display: block; width: 175%; height: auto; margin-left: -55%; }
.pim-reg { position: absolute; width: 9px; height: 9px; border: solid var(--grey-warm); }
.pim-reg.tl { top: 8px; left: 8px; border-width: 1px 0 0 1px; } .pim-reg.tr { top: 8px; right: 8px; border-width: 1px 1px 0 0; }
.pim-reg.bl { bottom: 8px; left: 8px; border-width: 0 0 1px 1px; } .pim-reg.br { bottom: 8px; right: 8px; border-width: 0 1px 1px 0; }
.pim-foot { margin-top: var(--space-md); }
.pim-note { font-size: 0.75rem; line-height: 1.5; color: var(--muted); max-width: 46ch; }
.pim-ring { transform-box: fill-box; transform-origin: center; opacity: 0; }
@media (prefers-reduced-motion: no-preference) {
  .pim.live .pim-ring { animation: pim-pulse 3s cubic-bezier(.16,1,.3,1) infinite; }
  .pim.live .pim-ring.b { animation-delay: 1.5s; }
}
@keyframes pim-pulse { 0% { transform: scale(.4); opacity: .7; } 70%, 100% { transform: scale(1); opacity: 0; } }
.pim-badge-ring { fill: var(--surface); stroke: var(--burgundy); stroke-width: 1.2; }
.pim-badge-icon { fill: none; stroke: var(--burgundy); stroke-linecap: square; stroke-linejoin: miter; }

/* "What leaves Chandigarh": unit chart, one symbol tile per published part */
.pim-man { margin-top: var(--space-xl); display: grid; gap: var(--space-lg); }
.pim-man-h { font-family: var(--font-archivo); font-variation-settings: "wdth" 125; font-size: clamp(1.25rem, 2vw, 1.625rem); font-weight: 650; letter-spacing: -0.02em; color: var(--ink); margin: 0 0 var(--space-xs); }
.pim-man-sub { font-size: 0.9375rem; line-height: 1.6; color: var(--body); margin: 0; max-width: 44ch; }
.pim-man-total { display: flex; align-items: baseline; gap: var(--space-xs); margin-top: var(--space-md); }
.pim-man-total b { font-family: var(--font-archivo); font-variation-settings: "wdth" 125; font-size: clamp(2.5rem, 5vw, 4rem); font-weight: 650; line-height: 1; letter-spacing: -0.04em; color: var(--burgundy); }
.pim-man-total span { font-size: 0.75rem; letter-spacing: 0.16em; text-transform: uppercase; font-weight: 600; color: var(--muted); }
.pim-rows { list-style: none; margin: 0; padding: 0; display: grid; gap: var(--space-sm); }
.pim-row { display: grid; grid-template-columns: minmax(0, 1fr); gap: var(--space-xs); padding-bottom: var(--space-sm); border-bottom: 1px solid var(--grey-cloud); }
.pim-row-k { display: flex; align-items: baseline; justify-content: space-between; gap: var(--space-sm); }
.pim-row-name { font-size: 0.9375rem; font-weight: 600; color: var(--ink); text-decoration: none; }
.pim-row-name:hover { color: var(--burgundy); }
.pim-row-n { font-family: var(--font-mono, monospace); font-size: 0.8125rem; color: var(--muted); white-space: nowrap; }
.pim-tiles { display: flex; flex-wrap: wrap; gap: 4px; }
.pim-tile { position: relative; display: inline-flex; align-items: center; justify-content: center; width: 44px; height: 44px;
  background: var(--surface); border: 1px solid var(--grey-warm); color: var(--burgundy); border-radius: var(--radius-card);
  transition: background-color 200ms cubic-bezier(.16,1,.3,1), color 200ms cubic-bezier(.16,1,.3,1), border-color 200ms; }
.pim-tile:hover, .pim-tile:focus-visible { background: var(--burgundy); border-color: var(--burgundy); color: var(--surface); }
.pim-tile:focus-visible { outline: 2px solid var(--burgundy); outline-offset: 2px; }
.pim-tile::after { content: attr(data-name); position: absolute; left: 50%; bottom: calc(100% + 6px); transform: translateX(-50%);
  padding: 4px 8px; background: var(--ink); color: var(--surface); font-size: 0.75rem; font-weight: 600; white-space: nowrap;
  border-radius: var(--radius-card); opacity: 0; pointer-events: none; transition: opacity 150ms; z-index: 2; }
.pim-tile:hover::after, .pim-tile:focus-visible::after { opacity: 1; }
.pim-man[data-armed='true'] .pim-tile { opacity: 0; transform: translate3d(0, 8px, 0) scale(.9); }
.pim-man[data-armed='true'][data-in='true'] .pim-tile { opacity: 1; transform: none;
  transition: opacity 500ms cubic-bezier(.16,1,.3,1) calc(var(--k) * 60ms), transform 500ms cubic-bezier(.16,1,.3,1) calc(var(--k) * 60ms),
    background-color 200ms, color 200ms, border-color 200ms; }
@media (prefers-reduced-motion: reduce) { .pim-man[data-armed='true'] .pim-tile { opacity: 1; transform: none; transition: none; } }
@media (min-width: 900px) {
  .pim-man { grid-template-columns: minmax(0, 4fr) minmax(0, 8fr); gap: var(--space-xl); align-items: start; }
  .pim-row { grid-template-columns: 220px minmax(0, 1fr); align-items: center; }
  .pim-row-k { flex-direction: column; gap: 2px; }
}
@media (min-width: 720px) {
  .pim-svg { width: 100%; margin-left: 0; }
}
@media (min-width: 900px) {
  .pim-head { grid-template-columns: minmax(0, 7fr) minmax(0, 5fr); gap: var(--space-xl); }
}
`;

export default function PanIndiaMap() {
  const sectionRef = useRef<HTMLElement>(null);
  const headingRef = useRef<HTMLHeadingElement>(null);
  const manRef = useRef<HTMLDivElement>(null);
  const [manArmed, setManArmed] = useState(false);
  const [manIn, setManIn] = useState(false);
  useMaskRise(headingRef);

  /* manifest tiles rise in once, in reading order, when the chart scrolls into view */
  useEffect(() => {
    const el = manRef.current;
    if (!el || typeof IntersectionObserver === 'undefined' || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    const io = new IntersectionObserver(([e]) => {
      setManArmed(true);
      if (e.isIntersecting) { setManIn(true); io.disconnect(); }
    }, { threshold: 0.3 });
    io.observe(el);
    return () => io.disconnect();
  }, []);

  /* looping pulse runs only while the section is on screen */
  useEffect(() => {
    const el = sectionRef.current;
    if (!el || typeof IntersectionObserver === 'undefined') return;
    const io = new IntersectionObserver(([e]) => el.classList.toggle('live', e.isIntersecting), { rootMargin: '80px' });
    io.observe(el);
    return () => io.disconnect();
  }, []);

  useGSAP(() => {
    const root = sectionRef.current;
    if (!root) return;
    const mm = gsap.matchMedia();
    mm.add('(prefers-reduced-motion: no-preference)', () => {
      const q = <T extends Element>(s: string) => gsap.utils.toArray<T>(s, root);
      const outline = root.querySelector<SVGPathElement>('.pim-outline');
      const worldDots = root.querySelector('.pim-world-dots');
      const indiaDots = root.querySelector('.pim-india-dots');
      const islands = root.querySelector('.pim-islands');
      const dArcs = q<SVGPathElement>('.pim-arc-d');
      const wArcs = q<SVGPathElement>('.pim-arc-w');
      const ends = q<SVGElement>('.pim-end');
      const lights = q<SVGCircleElement>('.pim-light');
      const origin = q<SVGElement>('.pim-origin');
      if (!outline || !worldDots || !indiaDots) return;

      gsap.set(worldDots, { opacity: 0 });
      gsap.set([indiaDots, islands], { opacity: 0 });
      gsap.set(outline, { strokeDasharray: 1, strokeDashoffset: 1, fillOpacity: 0 });
      gsap.set([...dArcs, ...wArcs], { strokeDasharray: 1, strokeDashoffset: 1 });
      gsap.set(ends, { opacity: 0 });
      gsap.set(lights, { opacity: 0 });
      gsap.set(origin, { opacity: 0 });

      /* light dot rides an arc once: transform only */
      const ride = (arc: SVGPathElement, light: SVGCircleElement, at: number, dur: number, tl: gsap.core.Timeline) => {
        const len = arc.getTotalLength();
        const o = { p: 0 };
        tl.set(light, { opacity: 1 }, at);
        tl.to(o, {
          p: 1, duration: dur, ease: EASINGS.powerInOut,
          onUpdate: () => {
            const pt = arc.getPointAtLength(o.p * len);
            gsap.set(light, { x: pt.x, y: pt.y });
          },
        }, at);
        tl.to(light, { opacity: 0, duration: DURATIONS.micro }, at + dur);
      };

      const tl = gsap.timeline({
        defaults: { ease: EASINGS.out },
        scrollTrigger: { trigger: root.querySelector('.pim-frame'), start: 'top 72%', once: true },
      });
      tl.to(worldDots, { opacity: 1, duration: DURATIONS.full, ease: EASINGS.out }, 0)
        .to(outline, { strokeDashoffset: 0, duration: DURATIONS.full, ease: EASINGS.inOut }, 0.2)
        .to(outline, { fillOpacity: 0.05, duration: DURATIONS.long, ease: EASINGS.out }, 0.9)
        .to([indiaDots, islands], { opacity: 1, duration: DURATIONS.long, ease: EASINGS.out }, 0.7)
        .to(origin, { opacity: 1, duration: DURATIONS.short, ease: EASINGS.out }, 1.0);
      dArcs.forEach((arc, i) => {
        const at = 1.2 + i * 0.07;
        tl.to(arc, { strokeDashoffset: 0, duration: DURATIONS.medium, ease: EASINGS.powerInOut }, at);
        tl.to(ends[i], { opacity: 1, duration: DURATIONS.short }, at + DURATIONS.medium);
        if (lights[i]) ride(arc, lights[i], at + DURATIONS.medium, DURATIONS.long, tl);
      });
      const wStart = 1.2 + dArcs.length * 0.07 + 0.5;
      wArcs.forEach((arc, i) => {
        const at = wStart + i * 0.14;
        const k = dArcs.length + i;
        tl.to(arc, { strokeDashoffset: 0, duration: DURATIONS.full, ease: EASINGS.inOut }, at);
        tl.to(ends[k], { opacity: 1, duration: DURATIONS.short }, at + DURATIONS.full);
        if (lights[k]) ride(arc, lights[k], at + DURATIONS.full, DURATIONS.full, tl);
      });

      return () => {
        tl.scrollTrigger?.kill();
        tl.kill();
        gsap.set([worldDots, indiaDots, islands, outline, ...dArcs, ...wArcs, ...ends, ...lights, ...origin], { clearProps: 'all' });
      };
    });
    return () => mm.revert();
  }, { scope: sectionRef });

  return (
    <section ref={sectionRef} className="pim" aria-labelledby="map-heading">
      <style>{CSS}</style>
      <div className="pim-inner">
        <div className="pim-head">
          <div>
            <div className="pim-label"><i aria-hidden="true" />Pan Bharat</div>
            <h2 id="map-heading" ref={headingRef} className="pim-h2">From Chandigarh to every corner of India.</h2>
            {/* COPY: drafted from verified facts (§5.10; Chandigarh base; Pan Bharat delivery network) — needs client approval */}
            <p className="pim-lead">
              From a single component to thousands of parts for a production line, we manufacture for businesses that build.
              Dispatch is from {site.contact.city} through our Pan Bharat delivery network.
            </p>
          </div>
          <ul className="pim-legend">
            <li>
              <svg width="22" height="22" viewBox="0 0 22 22" aria-hidden="true">
                <circle cx="11" cy="11" r="9" fill="none" stroke="var(--burgundy)" strokeWidth="1" opacity="0.4" />
                <circle cx="11" cy="11" r="5" fill="var(--burgundy)" />
              </svg>
              Origin: {site.contact.city}
            </li>
            <li>
              <svg width="22" height="22" viewBox="0 0 22 22" aria-hidden="true">
                <path d="M2 17Q11 2 20 6" fill="none" stroke="var(--burgundy)" strokeWidth="1.5" />
              </svg>
              Pan Bharat delivery network, today
            </li>
            <li>
              <svg width="22" height="22" viewBox="0 0 22 22" aria-hidden="true">
                <path d="M2 17Q11 2 20 6" fill="none" stroke="var(--burgundy)" strokeOpacity="0.55" strokeWidth="1.3" />
              </svg>
              The ambition: a globally recognised Indian manufacturing brand
            </li>
            <li>
              <svg width="22" height="22" viewBox="0 0 22 22" aria-hidden="true">
                <circle cx="11" cy="11" r="9.5" fill="var(--surface)" stroke="var(--burgundy)" strokeWidth="1.2" />
                <g transform="translate(5 5) scale(0.25)" fill="none" stroke="var(--burgundy)" strokeWidth="5">
                  {pictogramPaths['float-valve'].paths.map((d, i) => <path key={i} d={d} />)}
                </g>
              </svg>
              Parts on the move, drawn from our catalogue
            </li>
          </ul>
        </div>

        <figure style={{ margin: 0 }}>
          <div className="pim-frame">
            <div className="pim-stage">
            <svg
              className="pim-svg"
              viewBox={`${VB.x} ${VB.y} ${VB.w} ${VB.h}`}
              fill="none"
              role="img"
              aria-label="Dot-matrix world map with India highlighted in burgundy. Chandigarh is the origin of the Pan Bharat delivery network; the lighter arcs are illustrative and show ambition, not delivery destinations."
            >
              {/* world backdrop: muted dots */}
              <path className="pim-world-dots" d={WORLD_DOTS} stroke="var(--silver)" strokeOpacity="0.85" strokeWidth="2.6" strokeLinecap="round" strokeDasharray={`0 ${STEP_WORLD_U}`} />
              {/* India: Government of India depiction, enlarged in front of the world layer */}
              <g transform={IND_T}>
              <path className="pim-outline" d={INDIA_OUTLINE} pathLength={1} fill="var(--burgundy)" fillOpacity="0.05" stroke="var(--burgundy)" strokeWidth={1.4 / INDIA_SCALE} strokeLinejoin="round" />
              <path className="pim-islands" d={INDIA_ISLANDS} fill="var(--burgundy)" fillOpacity="0.55" stroke="var(--burgundy)" strokeWidth={0.5 / INDIA_SCALE} strokeLinejoin="round" />
              <path className="pim-india-dots" d={INDIA_DOTS} stroke="var(--burgundy)" strokeOpacity="0.8" strokeWidth={1.5 / INDIA_SCALE} strokeLinecap="round" strokeDasharray={`0 ${STEP_INDIA_U}`} />
              </g>

              {/* arcs: dense inside India, longer and lighter across the world */}
              {world.map((a, i) => (
                <path key={`w${i}`} className="pim-arc-w" d={a.d} pathLength={1} stroke="var(--burgundy)" strokeOpacity="0.55" strokeWidth="1.3" strokeLinecap="round" />
              ))}
              {domestic.map((a, i) => (
                <path key={`d${i}`} className="pim-arc-d" d={a.d} pathLength={1} stroke="var(--burgundy)" strokeOpacity="0.8" strokeWidth="1.2" strokeLinecap="round" />
              ))}
              {[...domestic, ...world].map((a, i) => {
                const badge = i < domestic.length ? BADGE[i] : undefined;
                if (badge) {
                  const k = ICON / 48;
                  return (
                    <g key={`e${i}`} className="pim-end" transform={`translate(${round(a.p.x)} ${round(a.p.y)})`}>
                      <title>{pictogramPaths[badge].title}</title>
                      <circle className="pim-badge-ring" r={BADGE_R} />
                      <g className="pim-badge-icon" transform={`translate(${-ICON / 2} ${-ICON / 2}) scale(${k})`} strokeWidth={1 / k}>
                        {pictogramPaths[badge].paths.map((d, j) => <path key={j} d={d} />)}
                      </g>
                    </g>
                  );
                }
                return <circle key={`e${i}`} visibility={inFrame(a.p) ? 'visible' : 'hidden'} className="pim-end" cx={a.p.x} cy={a.p.y} r={i < domestic.length ? 2.3 : 3} fill="var(--surface)" stroke="var(--burgundy)" strokeWidth="1.1" />;
              })}
              {[...domestic, ...world].map((_, i) => (
                <circle key={`l${i}`} className="pim-light" r="2.8" fill="var(--burgundy-bright)" />
              ))}

              {/* origin: Chandigarh */}
              <g className="pim-origin">
                <circle className="pim-ring" cx={ORIGIN.x} cy={ORIGIN.y} r="24" stroke="var(--burgundy)" strokeWidth="1.2" />
                <circle className="pim-ring b" cx={ORIGIN.x} cy={ORIGIN.y} r="24" stroke="var(--burgundy)" strokeWidth="1.2" />
                <circle cx={ORIGIN.x} cy={ORIGIN.y} r="5" fill="var(--burgundy)" stroke="var(--surface)" strokeWidth="1.5" />
              </g>
            </svg>
            </div>
            <span className="pim-reg tl" aria-hidden="true" /><span className="pim-reg tr" aria-hidden="true" />
            <span className="pim-reg bl" aria-hidden="true" /><span className="pim-reg br" aria-hidden="true" />
          </div>

          <figcaption className="pim-foot">
            <p className="pim-note">Illustrative. Arcs show direction of travel, not delivery destinations. Part symbols show what we make, not where each part goes.</p>
          </figcaption>
        </figure>

        {/* What leaves Chandigarh: the published catalogue as a unit chart */}
        <div ref={manRef} className="pim-man" data-armed={manArmed ? 'true' : undefined} data-in={manIn ? 'true' : undefined}>
          <div>
            <h3 className="pim-man-h">What leaves {site.contact.city}.</h3>
            <p className="pim-man-sub">Every symbol is one part in our catalogue, grouped by what it does inside the machine. Tap a part to see it.</p>
            <p className="pim-man-total"><b>{MANIFEST_TOTAL}</b><span>parts across {MANIFEST.length} families</span></p>
          </div>
          <ul className="pim-rows">
            {MANIFEST.map((r, ri) => {
              const before = MANIFEST.slice(0, ri).reduce((n, x) => n + x.parts.length, 0);
              return (
                <li key={r.g.id} className="pim-row">
                  <div className="pim-row-k">
                    <Link href={`/products/${r.g.slug}/`} className="pim-row-name">{r.g.name}</Link>
                    <span className="pim-row-n">{r.parts.length} {r.parts.length === 1 ? 'part' : 'parts'}</span>
                  </div>
                  <div className="pim-tiles">
                    {r.parts.map((p, pi) => (
                      <Link key={p.slug} href={`/products/${r.g.slug}/${p.slug}/`} className="pim-tile" data-name={p.name}
                        aria-label={p.name} style={{ ['--k' as string]: before + pi }}>
                        <PartPicto slug={p.slug} size={32} />
                      </Link>
                    ))}
                  </div>
                </li>
              );
            })}
          </ul>
        </div>
      </div>
    </section>
  );
}
